        var data = new SeedDataDto
        {
            Spielstaetten = new() { Venue("V1", Room("R1"), Room("R1")) },
            Veranstaltungen = new(),
        };

        await Assert.ThrowsAsync<InvalidOperationException>(() => importer.ImportAsync(data, ct));
    }

    [Fact]
