        };

        await Assert.ThrowsAsync<InvalidOperationException>(() => importer.ImportAsync(data, ct));
    }

    [Fact]
    public async Task ImportAsync_wirft_wenn_Sitzplatz_auf_einer_Gang_Spalte_liegt()
